// A base method passes differently typed arguments to an overridden method through `this`.
class Store {
  put(key) { return "store:" + key; }
  run(v) { return this.put(v); }
  fill() { return this.put(1) + ";" + this.put("two") + ";" + this.put(true); }
}
class MemStore extends Store {
  put(key) { return "mem:" + typeof key + ":" + key; }
}
class DiskStore extends MemStore {
  put(key, path) { return "disk:" + key + ":" + path; }
}
/** @returns {Store} */
function make(i) {
  return i === 0 ? new Store() : i === 1 ? new MemStore() : new DiskStore();
}
module.exports = { Store, MemStore, DiskStore, make };
